  "donation-direct-steps": { "en": "Open your app → Send Money → enter the number → enter your amount → review and confirm.", "bn": "নিজের অ্যাপ খুলুন → Send Money → নম্বর দিন → পরিমাণ দিন → যাচাই করে নিশ্চিত করুন।" },
  "donation-direct-safety": { "en": "Never share your PIN, OTP, or app password with Onnoy or anyone else.", "bn": "অন্বয় বা অন্য কারও সঙ্গে কখনো PIN, OTP বা অ্যাপের পাসওয়ার্ড শেয়ার করবেন না।" },
  "donation-number-copied": { "en": "Number copied. Open your payment app to continue.", "bn": "নম্বর কপি হয়েছে। চালিয়ে যেতে আপনার পেমেন্ট অ্যাপ খুলুন।" },
